            ["da-DK"] = ["Opdater OpenHikeMap", "OpenHikeMap v{0} er tilgængelig. Installeret version: v{1}.\n\nOpdater nu? Programmet lukkes og genstartes automatisk.", "Ja, opdater", "Ikke nu", "Henter version v{0}…", "Kontrollerer opdateringen…", "Forbereder opdatering og genstart…", "Opdateringen kunne ikke gennemføres. Prøv igen senere.", "Afslut igangværende handlinger, og kontrollér, at dine data kan gemmes, før du opdaterer.", "Version v{0} er tilgængelig, men indeholder ingen kompatibel Windows-pakke. Åbn udgivelsessiden?", "Åbn udgivelser", "Annuller", "Denne programfil kan ikke opdateres. Start den selvstændige udgave fra en mappe med skriveadgang, og prøv igen."],
            ["sv-SE"] = ["Uppdatera OpenHikeMap", "OpenHikeMap v{0} är tillgänglig. Installerad version: v{1}.\n\nUppdatera nu? Programmet stängs och startas om automatiskt.", "Ja, uppdatera", "Inte nu", "Hämtar version v{0}…", "Kontrollerar uppdateringen…", "Förbereder uppdatering och omstart…", "Uppdateringen kunde inte slutföras. Försök igen senare.", "Slutför pågående åtgärder och kontrollera att dina data kan sparas innan du uppdaterar.", "Version v{0} är tillgänglig, men innehåller inget kompatibelt Windows-paket. Öppna versionssidan?", "Öppna versioner", "Avbryt", "Den här programfilen kan inte uppdateras. Starta den fristående versionen från en skrivbar mapp och försök igen."],
